import numpy as np, itertools

lines=open('initial.xyz').read().split('\n')[2:]
atoms=[]
for l in lines:
    if l.strip():
        p=l.split(); atoms.append([p[0], np.array(list(map(float,p[1:4])))])
bonds=[tuple(map(int,l.split())) for l in open('bonds.txt') if l.strip()]
n=len(atoms)
pos=np.array([a[1] for a in atoms])
sym=[a[0] for a in atoms]

blen={}
for a,b in bonds:
    blen[(a,b)]=np.linalg.norm(pos[a]-pos[b])
adj={i:set() for i in range(n)}
for a,b in bonds:
    adj[a].add(b); adj[b].add(a)
excl=set()
for i in range(n):
    for j in adj[i]:
        excl.add((min(i,j),max(i,j)))
        for k in adj[j]:
            if k!=i: excl.add((min(i,k),max(i,k)))

def rmin(si,sj):
    h = (si=='H')+(sj=='H')
    if h==2: return 1.75
    if h==1: return 2.0
    return 2.3

pairs=[(i,j,rmin(sym[i],sym[j])) for i,j in itertools.combinations(range(n),2) if (i,j) not in excl]

def energy(pos):
    E=0.0
    for (a,b) in bonds:
        d=np.linalg.norm(pos[a]-pos[b]); t=blen[(a,b)]
        E+=200*(d-t)**2
    for i,j,r0 in pairs:
        d=np.linalg.norm(pos[i]-pos[j])
        if d<r0: E+=50*(r0-d)**2
    return E

def grad(pos):
    g=np.zeros_like(pos)
    for (a,b) in bonds:
        dv=pos[a]-pos[b]; d=np.linalg.norm(dv); t=blen[(a,b)]
        f=400*(d-t)/d
        g[a]+=f*dv; g[b]-=f*dv
    for i,j,r0 in pairs:
        dv=pos[i]-pos[j]; d=np.linalg.norm(dv)
        if d<r0:
            f=-100*(r0-d)/d
            g[i]+=f*dv; g[j]-=f*dv
    return g

fixed={0}  # Cr fixed
step=0.02
E=energy(pos)
for it in range(4000):
    g=grad(pos)
    for i in fixed: g[i]=0
    gn=np.linalg.norm(g)
    pos=pos-step*g/max(gn,1e-8)*np.sqrt(n)
    step*=0.999
    E2=energy(pos)
    if it%500==0:
        pass
E=energy(pos)
print('final classical E', round(E,2))
mind=99;pair=None
for i,j,r0 in pairs:
    d=np.linalg.norm(pos[i]-pos[j])
    if d<mind: mind=d; pair=(i,sym[i],j,sym[j])
print('min nonbonded', round(mind,2), pair)
# report key distances
for name,(a,b) in {'Cr-N1':(0,2),'Cr-N2':(0,3),'Cr-N3':(0,4),'Cr-N4':(0,5),'Cr-H':(0,1)}.items():
    print(name, round(np.linalg.norm(pos[a]-pos[b]),2))
with open('relaxed.xyz','w') as f:
    f.write(f"{n}\nrelaxed guess\n")
    for s,p in zip(sym,pos):
        f.write(f"{s} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n")
